724	
725	/// Cumulative connector (CPU offload / P2P) lookup counters, in tokens. A
726	/// request's lookup is settled exactly once, whether it reaches its first
727	/// prefill or leaves before it (cancelled, rejected, failed), so a lookup is
728	/// never lost with the request that made it.
729	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
730	pub struct ConnectorLookupCounters {
731	    /// Prompt tokens the connector was asked about, fixed when the query was
732	    /// issued: the prompt minus what sat in local KV at that moment.
733	    pub queries: u64,
734	    /// Of those, the tokens a committed load restored and the request's first
735	    /// prefill matched. A request that leaves before its first prefill used
736	    /// nothing it loaded.
737	    pub hits: u64,
738	}
739	
740	#[derive(Clone, Debug)]
741	pub struct PrefillRequestResult {
742	    pub(crate) request_id: RequestId,
743	    pub first_token: u32,
744	    pub first_token_logprob: Option<TokenLogprob>,
745	    pub(crate) prompt_logprobs: Option<Vec<Option<TokenLogprob>>>,
746	    /// Prompt tokens served from the prefix cache (KV reused, not recomputed).
747	    /// `None` when no lookup ran at all, which is the fact the /metrics
748	    /// counters need: a disabled cache or a prompt-scoring request counts
749	    /// nothing.
750	    pub cached_tokens: Option<usize>,
751	    /// How many of `cached_tokens` were restored from the external side (CPU
752	    /// offload / P2P) rather than found in local KV. `None` when no
753	    /// connector was consulted for this request; `Some(0)` when it was
754	    /// consulted and restored nothing.
755	    pub external_hit_tokens: Option<usize>,
756	    /// Whether the prompt is fully prefilled. When false this step ran a
757	    /// non-final chunk and `first_token` is meaningless.
758	    pub completed: bool,
759	    /// Prompt tokens with KV computed after this step (authoritative —
760	    /// includes prefix-cache hits the scheduler can't see).
761	    pub(crate) prefill_pos: usize,
762	}
