788	pub(crate) trait ModelExecutor: Send {
789	    fn block_size(&self) -> usize;
790	    fn max_request_blocks(&self) -> usize;
791	    fn max_context_tokens(&self) -> usize;
792	    fn max_decode_batch_size(&self) -> usize;
793	    fn available_blocks(&self) -> usize;
794	    fn is_stop_token(&self, token_id: u32) -> bool;
795	    fn drop_request(&mut self, request_id: RequestId) -> Result<()>;
796	
797	    fn execute_prefill(&mut self, plan: PrefillPlan<'_>) -> Result<PrefillResult>;
798	    fn execute_decode(&mut self, plan: DecodePlan<'_>) -> Result<DecodeResult>;
799	    fn execute_unified(&mut self, plan: UnifiedPlan<'_>) -> Result<UnifiedResult>;
800	
801	    /// Run one speculative draft round (propose `K` tokens per request). Only
802	    /// meaningful when [`Self::speculative_enabled`] is true.
803	    fn execute_speculative_draft(&mut self, _plan: DraftPlan<'_>) -> Result<DraftResult> {
