fn build_decode_request_results(
    lane: &LocalQwen3Lane,
    requests: &[DecodeStepItem],
    logits: &HiddenStates,
    row_offset: usize,
    tokens: &[u32],
) -> Result<Vec<DecodeRequestResult>> {
    let mut logprobs = gather_decode_logprobs(
        lane.model.device_ctx(),

        lane.model.device_ctx(),
        &DecodeRows {
            requests,
            logits,
