        anyhow::ensure!(
            !self.model.tp_graph_enabled(),
            "Qwen3 TP batch-1 graph was not captured by the startup sweep"
        );
        self.precapture_decode(bucket_idx, DecodeGraphUse::CaptureOnly)?;
